long Segment::ParseCues(long long off, long long& pos, long& len) {
if (m_pCues)
return 0;  // success

if (off < 0)
return -1;

long long total, avail;

const int status = m_pReader->Length(&total, &avail);

if (status < 0) // error
return status;

assert((total < 0) || (avail <= total));

pos = m_start + off;

if ((total < 0) || (pos >= total))
return 1; // don't bother parsing cues

const long long element_start = pos;
const long long segment_stop = (m_size < 0) ? -1 : m_start + m_size;

if ((pos + 1) > avail) {
len = 1;
return E_BUFFER_NOT_FULL;
}

long long result = GetUIntLength(m_pReader, pos, len);

if (result < 0) // error
return static_cast<long>(result);

if (result > 0) // underflow (weird)
{
len = 1;
return E_BUFFER_NOT_FULL;
}

if ((segment_stop >= 0) && ((pos + len) > segment_stop))
return E_FILE_FORMAT_INVALID;

if ((pos + len) > avail)
return E_BUFFER_NOT_FULL;


const long long idpos = pos;

  const long long id = ReadUInt(m_pReader, idpos, len);

if (id != 0x0C53BB6B)  // Cues ID
return E_FILE_FORMAT_INVALID;

pos += len; // consume ID
assert((segment_stop < 0) || (pos <= segment_stop));

// Read Size

if ((pos + 1) > avail) {
len = 1;
return E_BUFFER_NOT_FULL;
}

result = GetUIntLength(m_pReader, pos, len);

if (result < 0) // error
return static_cast<long>(result);

if (result > 0) // underflow (weird)
{
len = 1;
return E_BUFFER_NOT_FULL;
}

if ((segment_stop >= 0) && ((pos + len) > segment_stop))
return E_FILE_FORMAT_INVALID;

if ((pos + len) > avail)
return E_BUFFER_NOT_FULL;

const long long size = ReadUInt(m_pReader, pos, len);

if (size < 0) // error
return static_cast<long>(size);

if (size == 0) // weird, although technically not illegal
return 1; // done

pos += len; // consume length of size of element
assert((segment_stop < 0) || (pos <= segment_stop));

// Pos now points to start of payload

const long long element_stop = pos + size;

if ((segment_stop >= 0) && (element_stop > segment_stop))
return E_FILE_FORMAT_INVALID;

if ((total >= 0) && (element_stop > total))
return 1; // don't bother parsing anymore

len = static_cast<long>(size);

if (element_stop > avail)
return E_BUFFER_NOT_FULL;

const long long element_size = element_stop - element_start;


m_pCues =
new (std::nothrow) Cues(this, pos, size, element_start, element_size);
  assert(m_pCues);  // TODO

return 0;  // success
}
,"  const long long id = ReadUInt(m_pReader, idpos, len)

status_t BnOMX::onTransact(
uint32_t code, const Parcel &data, Parcel *reply, uint32_t flags) {
switch (code) {
case LIVES_LOCALLY:
{
CHECK_OMX_INTERFACE(IOMX, data, reply);
node_id node = (node_id)data.readInt32();
pid_t pid = (pid_t)data.readInt32();
reply->writeInt32(livesLocally(node, pid));

return OK;
}

case LIST_NODES:
{
CHECK_OMX_INTERFACE(IOMX, data, reply);

List<ComponentInfo> list;
listNodes(&list);

reply->writeInt32(list.size());
for (List<ComponentInfo>::iterator it = list.begin();
it != list.end(); ++it) {
ComponentInfo &cur = *it;

reply->writeString8(cur.mName);
reply->writeInt32(cur.mRoles.size());
for (List<String8>::iterator role_it = cur.mRoles.begin();
role_it != cur.mRoles.end(); ++role_it) {
reply->writeString8(*role_it);
}
}

return NO_ERROR;
}

case ALLOCATE_NODE:
{
CHECK_OMX_INTERFACE(IOMX, data, reply);

const char *name = data.readCString();

sp<IOMXObserver> observer =
interface_cast<IOMXObserver>(data.readStrongBinder());

node_id node;

status_t err = allocateNode(name, observer, &node);
reply->writeInt32(err);
if (err == OK) {
reply->writeInt32((int32_t)node);
}

return NO_ERROR;
}

case FREE_NODE:
{
CHECK_OMX_INTERFACE(IOMX, data, reply);

node_id node = (node_id)data.readInt32();

reply->writeInt32(freeNode(node));

return NO_ERROR;
}

case SEND_COMMAND:
{
CHECK_OMX_INTERFACE(IOMX, data, reply);

node_id node = (node_id)data.readInt32();

OMX_COMMANDTYPE cmd =
static_cast<OMX_COMMANDTYPE>(data.readInt32());

OMX_S32 param = data.readInt32();
reply->writeInt32(sendCommand(node, cmd, param));

return NO_ERROR;
}

case GET_PARAMETER:
case SET_PARAMETER:
case GET_CONFIG:
case SET_CONFIG:
case SET_INTERNAL_OPTION:
{
CHECK_OMX_INTERFACE(IOMX, data, reply);

node_id node = (node_id)data.readInt32();
OMX_INDEXTYPE index = static_cast<OMX_INDEXTYPE>(data.readInt32());

size_t size = data.readInt64();

status_t err = NOT_ENOUGH_DATA;

void *params = NULL;
size_t pageSize = 0;
size_t allocSize = 0;
            if (code != SET_INTERNAL_OPTION && size < 8) {
// we expect the structure to contain at least the size and
// version, 8 bytes total
ALOGE("b/27207275 (%zu)", size);
android_errorWriteLog(0x534e4554, "27207275");
} else {
err = NO_MEMORY;
pageSize = (size_t) sysconf(_SC_PAGE_SIZE);
if (size > SIZE_MAX - (pageSize * 2)) {
ALOGE("requested param size too big");
} else {
allocSize = (size + pageSize * 2) & ~(pageSize - 1);
params = mmap(NULL, allocSize, PROT_READ | PROT_WRITE,
MAP_PRIVATE | MAP_ANONYMOUS, -1 /* fd */, 0 /* offset */);
}
if (params != MAP_FAILED) {
err = data.read(params, size);
if (err != OK) {
android_errorWriteLog(0x534e4554, "26914474");

} else {
err = NOT_ENOUGH_DATA;
OMX_U32 declaredSize = *(OMX_U32*)params;
                        if (code != SET_INTERNAL_OPTION && declaredSize > size) {
// the buffer says it's bigger than it actually is
ALOGE("b/27207275 (%u/%zu)", declaredSize, size);
android_errorWriteLog(0x534e4554, "27207275");
} else {
// mark the last page as inaccessible, to avoid exploitation
// of codecs that access past the end of the allocation because
// they didn't check the size
mprotect((char*)params + allocSize - pageSize, pageSize, PROT_NONE);
switch (code) {
case GET_PARAMETER:
err = getParameter(node, index, params, size);
break;
case SET_PARAMETER:
err = setParameter(node, index, params, size);
break;
case GET_CONFIG:
err = getConfig(node, index, params, size);
break;
case SET_CONFIG:
err = setConfig(node, index, params, size);
break;
case SET_INTERNAL_OPTION:
{
InternalOptionType type =
(InternalOptionType)data.readInt32();

err = setInternalOption(node, index, type, params, size);
break;
}

default:
TRESPASS();
}
}
}
} else {
ALOGE("couldn't map: %s", strerror(errno));
}
}

reply->writeInt32(err);

if ((code == GET_PARAMETER || code == GET_CONFIG) && err == OK) {
reply->write(params, size);
}

if (params) {
munmap(params, allocSize);
}
params = NULL;

return NO_ERROR;
}

