mdfour_update(&m, (uchar *)map_ptr(buf, i, remainder), remainder);

mdfour_result(&m, (uchar *)sum);
rprintf(FERROR, "invalid checksum-choice for the --checksum option (%d)\n", checksum_type);
exit_cleanup(RERR_UNSUPPORTED);
}

close(fd);
unmap_file(buf);
}
