CARD32
fbOver (CARD32 x, CARD32 y)
{
CARD16  a = ~x >> 24;
CARD16  t;
CARD32  m,n,o,p;

m = FbOverU(x,y,0,a,t);
n = FbOverU(x,y,8,a,t);
o = FbOverU(x,y,16,a,t);
p = FbOverU(x,y,24,a,t);
return m|n|o|p;
}

CARD32
fbOver24 (CARD32 x, CARD32 y)
{
CARD16  a = ~x >> 24;
CARD16  t;
CARD32  m,n,o;

m = FbOverU(x,y,0,a,t);
n = FbOverU(x,y,8,a,t);
o = FbOverU(x,y,16,a,t);
return m|n|o;
}

CARD32
fbIn (CARD32 x, CARD8 y)
{
CARD16  a = y;
CARD16  t;
CARD32  m,n,o,p;

m = FbInU(x,0,a,t);
n = FbInU(x,8,a,t);
o = FbInU(x,16,a,t);
p = FbInU(x,24,a,t);
return m|n|o|p;
}

