/*
* Naming convention:
*
*  opSRCxMASKxDST
*/

void
fbCompositeSolidMask_nx8x8888 (CARD8      op,
PicturePtr pSrc,
PicturePtr pMask,
PicturePtr pDst,
INT16      xSrc,
INT16      ySrc,
INT16      xMask,
INT16      yMask,
INT16      xDst,
INT16      yDst,
CARD16     width,
CARD16     height)
{
CARD32	src, srca;
CARD32	*dstLine, *dst, d, dstMask;
CARD8	*maskLine, *mask, m;
FbStride	dstStride, maskStride;
CARD16	w;

fbComposeGetSolid(pSrc, src, pDst->format);

dstMask = FbFullMask (pDst->pDrawable->depth);
srca = src >> 24;
if (src == 0)
return;

fbComposeGetStart (pDst, xDst, yDst, CARD32, dstStride, dstLine, 1);
fbComposeGetStart (pMask, xMask, yMask, CARD8, maskStride, maskLine, 1);

while (height--)
{
dst = dstLine;
dstLine += dstStride;
mask = maskLine;
maskLine += maskStride;
w = width;

while (w--)
{
m = READ(mask++);
if (m == 0xff)
{
if (srca == 0xff)
WRITE(dst, src & dstMask);
else
WRITE(dst, fbOver (src, READ(dst)) & dstMask);
}
else if (m)
{
d = fbIn (src, m);
WRITE(dst, fbOver (d, READ(dst)) & dstMask);
}
dst++;
}
}

fbFinishAccess (pMask->pDrawable);
fbFinishAccess (pDst->pDrawable);
}

void
fbCompositeSolidMask_nx8888x8888C (CARD8      op,
PicturePtr pSrc,
PicturePtr pMask,
PicturePtr pDst,
INT16      xSrc,
INT16      ySrc,
INT16      xMask,
INT16      yMask,
INT16      xDst,
INT16      yDst,
CARD16     width,
CARD16     height)
{
CARD32	src, srca;
CARD32	*dstLine, *dst, d, dstMask;
CARD32	*maskLine, *mask, ma;
FbStride	dstStride, maskStride;
CARD16	w;
CARD32	m, n, o, p;

fbComposeGetSolid(pSrc, src, pDst->format);

dstMask = FbFullMask (pDst->pDrawable->depth);
srca = src >> 24;
if (src == 0)
return;

fbComposeGetStart (pDst, xDst, yDst, CARD32, dstStride, dstLine, 1);
fbComposeGetStart (pMask, xMask, yMask, CARD32, maskStride, maskLine, 1);

while (height--)
{
dst = dstLine;
dstLine += dstStride;
mask = maskLine;
maskLine += maskStride;
w = width;

while (w--)
{
ma = READ(mask++);
if (ma == 0xffffffff)
{
if (srca == 0xff)
WRITE(dst, src & dstMask);
else
WRITE(dst, fbOver (src, READ(dst)) & dstMask);
}
else if (ma)
{
d = READ(dst);
#define FbInOverC(src,srca,msk,dst,i,result) { \
CARD16  __a = FbGet8(msk,i); \
CARD32  __t, __ta; \
CARD32  __i; \
__t = FbIntMult (FbGet8(src,i), __a,__i); \
__ta = (CARD8) ~FbIntMult (srca, __a,__i); \
__t = __t + FbIntMult(FbGet8(dst,i),__ta,__i); \
__t = (CARD32) (CARD8) (__t | (-(__t >> 8))); \
result = __t << (i); \
}
FbInOverC (src, srca, ma, d, 0, m);
FbInOverC (src, srca, ma, d, 8, n);
FbInOverC (src, srca, ma, d, 16, o);
FbInOverC (src, srca, ma, d, 24, p);
WRITE(dst, m|n|o|p);
}
dst++;
}
}

fbFinishAccess (pMask->pDrawable);
fbFinishAccess (pDst->pDrawable);
}

#define srcAlphaCombine24(a,b) genericCombine24(a,b,srca,srcia)
void
fbCompositeSolidMask_nx8x0888 (CARD8      op,
PicturePtr pSrc,
PicturePtr pMask,
PicturePtr pDst,
INT16      xSrc,
INT16      ySrc,
INT16      xMask,
INT16      yMask,
INT16      xDst,
INT16      yDst,
CARD16     width,
CARD16     height)
{
CARD32	src, srca, srcia;
CARD8	*dstLine, *dst, *edst;
CARD8	*maskLine, *mask, m;
FbStride	dstStride, maskStride;
CARD16	w;
CARD32 rs,gs,bs,rd,gd,bd;

fbComposeGetSolid(pSrc, src, pDst->format);

srca = src >> 24;
srcia = 255-srca;
if (src == 0)
return;

rs=src&0xff;
gs=(src>>8)&0xff;
bs=(src>>16)&0xff;

fbComposeGetStart (pDst, xDst, yDst, CARD8, dstStride, dstLine, 3);
fbComposeGetStart (pMask, xMask, yMask, CARD8, maskStride, maskLine, 1);

while (height--)
{
/* fixme: cleanup unused */
unsigned long wt, wd;
CARD32 workingiDest;
CARD32 *widst;

edst = dst = dstLine;
dstLine += dstStride;
mask = maskLine;
maskLine += maskStride;
w = width;

#ifndef NO_MASKED_PACKED_READ
setupPackedReader(wd,wt,edst,widst,workingiDest);
#endif

while (w--)
{
#ifndef NO_MASKED_PACKED_READ
readPackedDest(rd);
readPackedDest(gd);
readPackedDest(bd);
#else
rd = READ(edst++);
gd = READ(edst++);
bd = READ(edst++);
#endif
m = READ(mask++);
if (m == 0xff)
{
if (srca == 0xff)
{
WRITE(dst++, rs);
WRITE(dst++, gs);
WRITE(dst++, bs);
}
else
{
WRITE(dst++, (srcAlphaCombine24(rs, rd)>>8));
WRITE(dst++, (srcAlphaCombine24(gs, gd)>>8));
WRITE(dst++, (srcAlphaCombine24(bs, bd)>>8));
}
}
else if (m)
{
int na=(srca*(int)m)>>8;
int nia=255-na;
WRITE(dst++, (genericCombine24(rs, rd, na, nia)>>8));
WRITE(dst++, (genericCombine24(gs, gd, na, nia)>>8));
WRITE(dst++, (genericCombine24(bs, bd, na, nia)>>8));
}
else
{
dst+=3;
}
}
}

fbFinishAccess (pMask->pDrawable);
fbFinishAccess (pDst->pDrawable);
}

void
fbCompositeSolidMask_nx8x0565 (CARD8      op,
PicturePtr pSrc,
PicturePtr pMask,
PicturePtr pDst,
INT16      xSrc,
INT16      ySrc,
INT16      xMask,
INT16      yMask,
INT16      xDst,
INT16      yDst,
CARD16     width,
CARD16     height)
{
CARD32	src, srca8, srca5;
CARD16	*dstLine, *dst;
CARD16	d;
CARD32	t;
CARD8	*maskLine, *mask, m;
FbStride	dstStride, maskStride;
CARD16	w,src16;

fbComposeGetSolid(pSrc, src, pDst->format);

if (src == 0)
return;

srca8 = (src >> 24);
srca5 = (srca8 >> 3);
src16 = cvt8888to0565(src);

fbComposeGetStart (pDst, xDst, yDst, CARD16, dstStride, dstLine, 1);
fbComposeGetStart (pMask, xMask, yMask, CARD8, maskStride, maskLine, 1);

while (height--)
{
dst = dstLine;
dstLine += dstStride;
mask = maskLine;
maskLine += maskStride;
w = width;

while (w--)
{
m = READ(mask++);
if (m == 0)
dst++;
else if (srca5 == (0xff >> 3))
{
if (m == 0xff)
WRITE(dst++, src16);
else
{
d = READ(dst);
m >>= 3;
inOver0565 (m, src16, d, dst++);
}
}
else
{
d = READ(dst);
if (m == 0xff)
{
t = fbOver24 (src, cvt0565to0888 (d));
}
else
{
t = fbIn (src, m);
t = fbOver (t, cvt0565to0888 (d));
}
WRITE(dst++, cvt8888to0565 (t));
}
}
}

fbFinishAccess (pMask->pDrawable);
fbFinishAccess (pDst->pDrawable);
}

