void
fbCompositeSrcAdd_8000x8000 (CARD8	op,
PicturePtr pSrc,
PicturePtr pMask,
PicturePtr pDst,
INT16      xSrc,
INT16      ySrc,
INT16      xMask,
INT16      yMask,
INT16      xDst,
INT16      yDst,
CARD16     width,
CARD16     height)
{
CARD8	*dstLine, *dst;
CARD8	*srcLine, *src;
FbStride	dstStride, srcStride;
CARD16	w;
CARD8	s, d;
CARD16	t;

fbComposeGetStart (pSrc, xSrc, ySrc, CARD8, srcStride, srcLine, 1);
fbComposeGetStart (pDst, xDst, yDst, CARD8, dstStride, dstLine, 1);

while (height--)
{
dst = dstLine;
dstLine += dstStride;
src = srcLine;
srcLine += srcStride;
w = width;

while (w--)
{
s = READ(src++);
if (s)
{
if (s != 0xff)
{
d = READ(dst);
t = d + s;
s = t | (0 - (t >> 8));
}
WRITE(dst, s);
}
dst++;
}
}

fbFinishAccess (pDst->pDrawable);
fbFinishAccess (pSrc->pDrawable);
}

void
fbCompositeSrcAdd_8888x8888 (CARD8	op,
PicturePtr pSrc,
PicturePtr pMask,
PicturePtr pDst,
INT16      xSrc,
INT16      ySrc,
INT16      xMask,
INT16      yMask,
INT16      xDst,
INT16      yDst,
CARD16     width,
CARD16     height)
{
CARD32	*dstLine, *dst;
CARD32	*srcLine, *src;
FbStride	dstStride, srcStride;
CARD16	w;
CARD32	s, d;
CARD16	t;
CARD32	m,n,o,p;

fbComposeGetStart (pSrc, xSrc, ySrc, CARD32, srcStride, srcLine, 1);
fbComposeGetStart (pDst, xDst, yDst, CARD32, dstStride, dstLine, 1);

while (height--)
{
dst = dstLine;
dstLine += dstStride;
src = srcLine;
srcLine += srcStride;
w = width;

while (w--)
{
s = READ(src++);
if (s)
{
if (s != 0xffffffff)
{
d = READ(dst);
if (d)
{
m = FbAdd(s,d,0,t);
n = FbAdd(s,d,8,t);
o = FbAdd(s,d,16,t);
p = FbAdd(s,d,24,t);
s = m|n|o|p;
}
}
WRITE(dst, s);
}
dst++;
}
}

fbFinishAccess (pDst->pDrawable);
fbFinishAccess (pSrc->pDrawable);
}

static void
fbCompositeSrcAdd_8888x8x8 (CARD8      op,
PicturePtr pSrc,
PicturePtr pMask,
PicturePtr pDst,
INT16      xSrc,
INT16      ySrc,
INT16      xMask,
INT16      yMask,
INT16      xDst,
INT16      yDst,
CARD16     width,
CARD16     height)
{
CARD8	*dstLine, *dst;
CARD8	*maskLine, *mask;
FbStride	dstStride, maskStride;
CARD16	w;
CARD32	src;
CARD8	sa;

fbComposeGetStart (pDst, xDst, yDst, CARD8, dstStride, dstLine, 1);
fbComposeGetStart (pMask, xMask, yMask, CARD8, maskStride, maskLine, 1);
fbComposeGetSolid (pSrc, src, pDst->format);
sa = (src >> 24);

while (height--)
{
dst = dstLine;
dstLine += dstStride;
mask = maskLine;
maskLine += maskStride;
w = width;

while (w--)
{
CARD16	tmp;
CARD16	a;
CARD32	m, d;
CARD32	r;

a = READ(mask++);
d = READ(dst);

m = FbInU (sa, 0, a, tmp);
r = FbAdd (m, d, 0, tmp);

WRITE(dst++, r);
}
}

fbFinishAccess(pDst->pDrawable);
fbFinishAccess(pMask->pDrawable);
}

void
fbCompositeSrcAdd_1000x1000 (CARD8	op,
PicturePtr pSrc,
PicturePtr pMask,
PicturePtr pDst,
INT16      xSrc,
INT16      ySrc,
INT16      xMask,
INT16      yMask,
INT16      xDst,
INT16      yDst,
CARD16     width,
CARD16     height)
{
FbBits	*dstBits, *srcBits;
FbStride	dstStride, srcStride;
int		dstBpp, srcBpp;
int		dstXoff, dstYoff;
int		srcXoff, srcYoff;

fbGetDrawable(pSrc->pDrawable, srcBits, srcStride, srcBpp, srcXoff, srcYoff);

fbGetDrawable(pDst->pDrawable, dstBits, dstStride, dstBpp, dstXoff, dstYoff);

fbBlt (srcBits + srcStride * (ySrc + srcYoff),
srcStride,
xSrc + srcXoff,

dstBits + dstStride * (yDst + dstYoff),
dstStride,
xDst + dstXoff,

width,
height,

GXor,
FB_ALLONES,
srcBpp,

FALSE,
FALSE);

fbFinishAccess(pDst->pDrawable);
fbFinishAccess(pSrc->pDrawable);
}

void
fbCompositeSolidMask_nx1xn (CARD8      op,
PicturePtr pSrc,
PicturePtr pMask,
PicturePtr pDst,
INT16      xSrc,
INT16      ySrc,
INT16      xMask,
INT16      yMask,
INT16      xDst,
INT16      yDst,
CARD16     width,
CARD16     height)
{
FbBits	*dstBits;
FbStip	*maskBits;
FbStride	dstStride, maskStride;
int		dstBpp, maskBpp;
int		dstXoff, dstYoff;
int		maskXoff, maskYoff;
FbBits	src;

fbComposeGetSolid(pSrc, src, pDst->format);
fbGetStipDrawable (pMask->pDrawable, maskBits, maskStride, maskBpp, maskXoff, maskYoff);
fbGetDrawable (pDst->pDrawable, dstBits, dstStride, dstBpp, dstXoff, dstYoff);

switch (dstBpp) {
case 32:
break;
case 24:
break;
case 16:
src = cvt8888to0565(src);
break;
}

src = fbReplicatePixel (src, dstBpp);

fbBltOne (maskBits + maskStride * (yMask + maskYoff),
maskStride,
xMask + maskXoff,

dstBits + dstStride * (yDst + dstYoff),
dstStride,
(xDst + dstXoff) * dstBpp,
dstBpp,

width * dstBpp,
height,

0x0,
src,
FB_ALLONES,
0x0);

fbFinishAccess (pDst->pDrawable);
fbFinishAccess (pMask->pDrawable);
}

# define mod(a,b)	((b) == 1 ? 0 : (a) >= 0 ? (a) % (b) : (b) - (-a) % (b))

/*
* Apply a constant alpha value in an over computation
*/
static void
fbCompositeSrcSrc_nxn  (CARD8	   op,
PicturePtr pSrc,
PicturePtr pMask,
PicturePtr pDst,
INT16      xSrc,
INT16      ySrc,
INT16      xMask,
INT16      yMask,
INT16      xDst,
INT16      yDst,
CARD16     width,
CARD16     height);

static void
fbCompositeTrans_0565xnx0565(CARD8      op,
PicturePtr pSrc,
PicturePtr pMask,
PicturePtr pDst,
INT16      xSrc,
INT16      ySrc,
INT16      xMask,
INT16      yMask,
INT16      xDst,
INT16      yDst,
CARD16     width,
CARD16     height)
{
CARD16	*dstLine, *dst;
CARD16	*srcLine, *src;
FbStride	dstStride, srcStride;
CARD16	w;
FbBits	mask;
CARD8	maskAlpha;
CARD16	s_16, d_16;
CARD32	s_32, d_32;

fbComposeGetSolid (pMask, mask, pDst->format);
maskAlpha = mask >> 27;

if (!maskAlpha)
return;
if (maskAlpha == 0xff)
{
fbCompositeSrcSrc_nxn (PictOpSrc, pSrc, pMask, pDst,
xSrc, ySrc, xMask, yMask, xDst, yDst,
width, height);
return;
}

fbComposeGetStart (pSrc, xSrc, ySrc, CARD16, srcStride, srcLine, 1);
fbComposeGetStart (pDst, xDst, yDst, CARD16, dstStride, dstLine, 1);

while (height--)
{
CARD32 *isrc, *idst;
dst = dstLine;
dstLine += dstStride;
src = srcLine;
srcLine += srcStride;
w = width;

if(((long)src&1)==1)
{
s_16 = READ(src++);
d_16 = READ(dst);
inOver0565(maskAlpha, s_16, d_16, dst++);
w--;
}
isrc=(CARD32 *)src;
if(((long)dst&1)==0)
{
idst=(CARD32 *)dst;
while (w>1)
{
s_32 = READ(isrc++);
d_32 = READ(idst);
inOver2x0565(maskAlpha, s_32, d_32, idst++);
w-=2;
}
dst=(CARD16 *)idst;
}
else
{
while (w > 1)
{
s_32 = READ(isrc++);
#if IMAGE_BYTE_ORDER == LSBFirst
s_16=s_32&0xffff;
#else
s_16=s_32>>16;
#endif
d_16 = READ(dst);
inOver0565 (maskAlpha, s_16, d_16, dst++);
#if IMAGE_BYTE_ORDER == LSBFirst
s_16=s_32>>16;
#else
s_16=s_32&0xffff;
#endif
d_16 = READ(dst);
inOver0565(maskAlpha, s_16, d_16, dst++);
w-=2;
}
}
src=(CARD16 *)isrc;
if(w!=0)
{
s_16 = READ(src);
d_16 = READ(dst);
inOver0565(maskAlpha, s_16, d_16, dst);
}
}

fbFinishAccess (pSrc->pDrawable);
fbFinishAccess (pDst->pDrawable);
}

/* macros for "i can't believe it's not fast" packed pixel handling */
#define alphamaskCombine24(a,b) genericCombine24(a,b,maskAlpha,maskiAlpha)

static void
fbCompositeTrans_0888xnx0888(CARD8      op,
PicturePtr pSrc,
PicturePtr pMask,
PicturePtr pDst,
INT16      xSrc,
INT16      ySrc,
INT16      xMask,
INT16      yMask,
INT16      xDst,
INT16      yDst,
CARD16     width,
CARD16     height)
{
CARD8	*dstLine, *dst,*idst;
CARD8	*srcLine, *src;
FbStride	dstStride, srcStride;
CARD16	w;
FbBits	mask;
CARD16	maskAlpha,maskiAlpha;

fbComposeGetSolid (pMask, mask, pDst->format);
maskAlpha = mask >> 24;
maskiAlpha= 255-maskAlpha;

if (!maskAlpha)
return;
/*
if (maskAlpha == 0xff)
{
fbCompositeSrc_0888x0888 (op, pSrc, pMask, pDst,
xSrc, ySrc, xMask, yMask, xDst, yDst,
width, height);
return;
}
*/

fbComposeGetStart (pSrc, xSrc, ySrc, CARD8, srcStride, srcLine, 3);
fbComposeGetStart (pDst, xDst, yDst, CARD8, dstStride, dstLine, 3);

{
unsigned long ws,wt;
CARD32 workingSource;
CARD32 *wsrc, *wdst, *widst;
CARD32 rs, rd, nd;
CARD8 *isrc;


/* are xSrc and xDst at the same alignment?  if not, we need to be complicated :) */
/* if(0==0) */
if ((((xSrc * 3) & 3) != ((xDst * 3) & 3)) ||
((srcStride & 3) != (dstStride & 3)))
{
while (height--)
{
dst = dstLine;
dstLine += dstStride;
isrc = src = srcLine;
srcLine += srcStride;
w = width*3;

setupPackedReader(ws,wt,isrc,wsrc,workingSource);

/* get to word aligned */
switch(~(long)dst&3)
{
case 1:
readPackedSource(rs);
/* *dst++=alphamaskCombine24(rs, *dst)>>8; */
rd = READ(dst);  /* make gcc happy.  hope it doens't cost us too much performance*/
WRITE(dst++, alphamaskCombine24(rs, rd) >> 8);
w--; if(w==0) break;
case 2:
readPackedSource(rs);
rd = READ(dst);
WRITE(dst++, alphamaskCombine24(rs, rd) >> 8);
w--; if(w==0) break;
case 3:
readPackedSource(rs);
rd = READ(dst);
WRITE(dst++,alphamaskCombine24(rs, rd) >> 8);
w--; if(w==0) break;
}
wdst=(CARD32 *)dst;
while (w>3)
{
rs=READ(wsrc++);
/* FIXME: write a special readPackedWord macro, which knows how to
* halfword combine
*/
#if IMAGE_BYTE_ORDER == LSBFirst
rd=READ(wdst);
readPackedSource(nd);
readPackedSource(rs);
nd|=rs<<8;
readPackedSource(rs);
nd|=rs<<16;
readPackedSource(rs);
nd|=rs<<24;
#else
readPackedSource(nd);
nd<<=24;
readPackedSource(rs);
nd|=rs<<16;
readPackedSource(rs);
nd|=rs<<8;
readPackedSource(rs);
nd|=rs;
#endif
inOver0888(maskAlpha, nd, rd, wdst++);
w-=4;
}
src=(CARD8 *)wdst;
switch(w)
{
case 3:
readPackedSource(rs);
rd=READ(dst);
WRITE(dst++,alphamaskCombine24(rs, rd)>>8);
case 2:
readPackedSource(rs);
rd = READ(dst);
WRITE(dst++, alphamaskCombine24(rs, rd)>>8);
case 1:
readPackedSource(rs);
rd = READ(dst);
WRITE(dst++, alphamaskCombine24(rs, rd)>>8);
}
}
}
else
{
while (height--)
{
idst=dst = dstLine;
dstLine += dstStride;
src = srcLine;
srcLine += srcStride;
w = width*3;
/* get to word aligned */
switch(~(long)src&3)
{
case 1:
rd=alphamaskCombine24(READ(src++), READ(dst))>>8;
WRITE(dst++, rd);
w--; if(w==0) break;
case 2:
rd=alphamaskCombine24(READ(src++), READ(dst))>>8;
WRITE(dst++, rd);
w--; if(w==0) break;
case 3:
rd=alphamaskCombine24(READ(src++), READ(dst))>>8;
WRITE(dst++, rd);
w--; if(w==0) break;
}
wsrc=(CARD32 *)src;
widst=(CARD32 *)dst;
while(w>3)
{
rs = READ(wsrc++);
rd = READ(widst);
inOver0888 (maskAlpha, rs, rd, widst++);
w-=4;
}
src=(CARD8 *)wsrc;
dst=(CARD8 *)widst;
switch(w)
{
case 3:
rd=alphamaskCombine24(READ(src++), READ(dst))>>8;
WRITE(dst++, rd);
case 2:
rd=alphamaskCombine24(READ(src++), READ(dst))>>8;
WRITE(dst++, rd);
case 1:
rd=alphamaskCombine24(READ(src++), READ(dst))>>8;
WRITE(dst++, rd);
}
}
}
}
}

